import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI } from '../services/api';

const Home = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchFeaturedRooms();
  }, []);

  const fetchFeaturedRooms = async () => {
    try {
      const response = await roomAPI.getAll({ limit: 3 });
      setRooms(response.data.rooms);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>Bienvenue sur la plateforme de réservation de salles</h1>
        <p className="description">
          Réservez la salle parfaite pour vos réunions, conférences ou événements.
          Des espaces professionnels dans toute la France.
        </p>
        
        <div className="cta-buttons">
          <Link to="/rooms" className="btn btn-primary">
            Voir toutes les salles
          </Link>
          <Link to="/register" className="btn btn-secondary">
            Créer un compte
          </Link>
        </div>
      </div>

      <div className="card">
        <h2>Salles populaires</h2>
        {loading ? (
          <p>Chargement des salles...</p>
        ) : rooms.length > 0 ? (
          <div className="rooms-grid">
            {rooms.map(room => (
              <div key={room.id} className="room-card">
                <h3>{room.title}</h3>
                <p>{room.city} • {room.capacity} personnes</p>
                <p className="price">{room.price_per_hour}€/heure</p>
                <Link to={`/rooms/${room.id}`} className="btn btn-primary">
                  Voir détails
                </Link>
              </div>
            ))}
          </div>
        ) : (
          <p>Aucune salle disponible pour le moment.</p>
        )}
      </div>

      <div className="card features">
        <h2>Pourquoi choisir notre plateforme ?</h2>
        <div className="features-grid">
          <div className="feature">
            <h3>🏢 Large choix</h3>
            <p>Des salles de toutes tailles et pour tous les budgets</p>
          </div>
          <div className="feature">
            <h3>📍 Localisation</h3>
            <p>Des selles bien situées dans les centres-villes</p>
          </div>
          <div className="feature">
            <h3>💰 Transparence</h3>
            <p>Pas de frais cachés, prix affichés à l'heure</p>
          </div>
          <div className="feature">
            <h3>🔒 Sécurité</h3>
            <p>Paiement sécurisé et système de confiance</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
